xf:group.script:
				// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
var splitter = {};
				splitter.vertical = options.orientation !== 'vertical';
				splitter.minSize = 0;
				splitter.splitterSize = 20;

				if (options.position)
					splitter.position = options.position;

				switch (options.collapse) {
					case 'left':
					case 'right':
						splitter.collapse = options.collapse;
						break;
					case 'top':
						splitter.collapse = 'up';
						break;
					case 'bottom':
						splitter.collapse = 'down';
						break;
				}

				if (!$.fn.enhsplitter) {
					var count = 0;
					scwin.wait = function() {
						count++;

						if (count > 5) {
							//alert(app.getLocale('AltCompLoadErr')); // TODO [seri36]
							//app.logout();
							return;
						}

						setTimeout(function() {
							if (!$.fn.enhsplitter)
								scwin.wait();
							else
								scwin.__getJq(udc_obj.render).enhsplitter(splitter);
						}, 100);
					};

					scwin.wait();
				} else {
					setTimeout(function() {
						scwin.__getJq(udc_obj.render).enhsplitter(splitter);
					});
				}
